{path=src/test/java/com/wolinski/shop/orders/internal/OrderServiceExpireStaleTest.java, content=package com.wolinski.shop.orders.internal;

import static org.junit.jupiter.api.Assertions.assertEquals;

import com.wolinski.shop.money.Money;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneId;
import org.junit.jupiter.api.Test;

class OrderServiceExpireStaleTest {

    // 2026-10-31 12:00 Warsaw (CET, UTC+1)
    private final Clock clock = Clock.fixed(Instant.parse("2026-10-31T11:00:00Z"), ZoneId.of("UTC"));

    private final OrderRepository repository = new OrderRepository();
    private final OrderService service = new OrderService(repository, clock);

    @Test
    void cancelsPlacedOrdersOlderThan30DaysAndCountsThem() {
        String old = place("2026-09-30T10:00:00Z"); // 31 days before today in Warsaw
        String recent = place("2026-10-01T10:00:00Z"); // 30 days before: not yet stale

        assertEquals(1, service.expireStale());

        assertEquals("CANCELLED", repository.get(old).status());
        assertEquals("PLACED", repository.get(recent).status());
    }

    @Test
    void leavesOrdersInOtherStatusesAlone() {
        String confirmed = place("2026-08-01T10:00:00Z");
        repository.get(confirmed).changeStatus("CONFIRMED");
        String cancelled = place("2026-08-01T10:00:00Z");
        repository.get(cancelled).changeStatus("CANCELLED");

        assertEquals(0, service.expireStale());

        assertEquals("CONFIRMED", repository.get(confirmed).status());
        assertEquals("CANCELLED", repository.get(cancelled).status());
    }

    @Test
    void usesTheWarsawBusinessDayNotUtc() {
        // 2026-09-30 23:30 Warsaw (CEST, UTC+2) is 21:30 UTC on 30 Sep, still 31 Warsaw days before 31 Oct.
        // Placed at 2026-09-30T23:30 Warsaw -> Warsaw date 2026-09-30, which is before the cutoff 2026-10-01.
        String lateEvening = place("2026-09-30T21:30:00Z");
        // 2026-10-01 00:30 Warsaw is 2026-09-30T22:30Z: Warsaw date 2026-10-01, not stale.
        String justAfterMidnight = place("2026-09-30T22:30:00Z");

        assertEquals(1, service.expireStale());

        assertEquals("CANCELLED", repository.get(lateEvening).status());
        assertEquals("PLACED", repository.get(justAfterMidnight).status());
    }

    @Test
    void returnsZeroWhenNothingIsStale() {
        place("2026-10-30T10:00:00Z");

        assertEquals(0, service.expireStale());
    }

    @Test
    void isIdempotent() {
        place("2026-09-01T10:00:00Z");

        assertEquals(1, service.expireStale());
        assertEquals(0, service.expireStale());
    }

    private String place(String placedAt) {
        return service.place("c-1", Money.pln(1000), Instant.parse(placedAt));
    }
}
}

